 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objects.append(cells)
    candidates = [cells for cells in objects if len({grid[y][x] for y,x in cells}) == 3]
    if len(candidates) != 1:
        raise ValueError('expected one object with three colors')
    cells = candidates[0]
    r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
    c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
